def check_javascript_sdk_script(errors):
    script = read(JS_SDK_TEST_COMMAND)
    require(
        'NODE_OVERRIDE="${KAGEMUSHA_RECURSIVE_SPEND_JS_SDK_NODE_BIN:-}"' in script,
        "Kagemusha JavaScript SDK script must keep the documented Node override variable",
        errors,
    )
    require(
        "resolve_node_20_bin()" in script and "is_node_20_bin()" in script,
        "Kagemusha JavaScript SDK script must resolve Node 20 before falling back to node",
        errors,
    )
    require(
        'NODE_BIN="$(resolve_node_20_bin)"' in script,
        "Kagemusha JavaScript SDK script must use the Node 20 resolver",
        errors,
    )
    require(
        'NODE_VERSION="$("${NODE_BIN}" --version)"' in script,
        "Kagemusha JavaScript SDK script must print the selected Node version",
        errors,
    )
    require(
        'printf \'%s\\n\' "${NODE_VERSION}"' in script,
        "Kagemusha JavaScript SDK script must emit the selected Node version",
        errors,
    )
    require(
        "v20.*) ;;" in script,
        "Kagemusha JavaScript SDK script must reject non-Node-20 runtimes",
        errors,
    )
    require(
        "native_binding_is_ready()" in script
        and 'NATIVE_BINDING_PROBE_QUIET="${quiet}" "${NODE_BIN}" --input-type=module' in script
        and 'native_binding_is_ready quiet' in script
        and 'const quiet = process.env.NATIVE_BINDING_PROBE_QUIET === "quiet";' in script
        and "verifyNativeBinding(bindingPath, { manifestPath })" in script
        and 'if [[ -n "${IROHA_JS_NATIVE_DIR:-}" ]]; then' in script,
        "Kagemusha JavaScript SDK script must verify explicit native binding overrides before tests",
        errors,
    )
    require(
        "prepare_native_binding()" in script
        and 'TEMP_NATIVE_DIR="$(mktemp -d "${TMPDIR:-/tmp}/iroha-js-native-kagemusha.XXXXXX")"' in script
        and 'IROHA_JS_NATIVE_DIR="${TEMP_NATIVE_DIR}" "${NODE_BIN}" ./scripts/build-native.mjs' in script
        and 'IROHA_JS_NATIVE_DIR="${TEMP_NATIVE_DIR}" "${NODE_BIN}" ./scripts/copy-native.mjs' in script
        and 'export IROHA_JS_NATIVE_DIR="${TEMP_NATIVE_DIR}"' in script,
        "Kagemusha JavaScript SDK script must prepare a verified temporary native binding when repo artifacts are stale",
        errors,
    )
    require(
        "cleanup_temp_native_dir()" in script
        and "trap cleanup_temp_native_dir EXIT" in script,
        "Kagemusha JavaScript SDK script must clean up temporary native build artifacts",
        errors,
    )
    prepare_call = script.find("\nprepare_native_binding\n")
    test_call = script.find('\n"${NODE_BIN}" --test ')
    require(
        prepare_call != -1 and test_call != -1 and prepare_call < test_call,
        "Kagemusha JavaScript SDK script must prepare a verified native binding before running tests",
        errors,
    )
    require(
        "Kagemusha recursive spend|Kagemusha record-backed|Kagemusha .* SDK runner|browser crypto exposes native-only helpers as safe stubs|buildKagemusha" in script
        and "privacy native availability probes build and verify with Norito request archives" in script
        and "privacy native wrappers require binary Norito request archives" in script
        and "privacy algorithm JS catalogs reject malformed internal review evidence" in script
        and "fromAccount rejects control and Unicode-confusable curve algorithm aliases" in script
        and "offline cash configuration snapshot requires cached issuer key and ABI" in script
        and "canonical request signing: rejects padded auth fields" in script
        and "streamEvents rejects unsupported production backend event filters before fetch" in script
        and "streamEvents rejects malformed verifying key event names before fetch" in script
        and "streamEvents rejects malformed proof event hashes before fetch" in script
        and "ZK-ACE verifier-key references reject padded selector metadata" in script
        and "privacy proof envelopes preserve pending production backend tags" in script
        and "verifyIdentifierResolutionReceipt rejects adversarial receipt mutations" in script
        and "encodeIdentifierResolutionReceiptPayload rejects non-exact execution tags" in script
        and "encodeIdentifierResolutionReceiptAttestation rejects padded proof backend" in script
        and "verifyIdentifierResolutionReceipt matches shared receipt vectors" in script
        and "ToriiClient attaches canonical signing headers for app endpoints" in script
        and "ToriiClient canonical auth uses raw Node transport for UTF-8 account headers" in script
        and "ToriiClient canonical auth rejects UTF-8 account headers when no supported transport is available" in script
        and "ToriiClient canonical auth rejects non-byte private key arrays" in script
        and "subscription plan and create endpoints send normalized payloads" in script
        and "subscription action endpoints send normalized payloads" in script
        and "getSubscription returns null on 404" in script
        and "buildConnectWebSocketUrl rejects token query parameters" in script
        and "buildConnectWebSocketUrl rejects endpoint host overrides" in script
        and "buildConnectWebSocketUrl rejects endpoint protocol mismatches" in script
        and "openConnectWebSocket injects Sec-WebSocket-Protocol when headers are unavailable" in script
        and "openConnectWebSocket emits telemetry when allowInsecure is used" in script
        and "resolveAliasByIndex enforces non-negative indices before issuing requests" in script
        and "resolveAlias attaches canonical auth when provided" in script
        and "lookupAliasesByAccount validates options before issuing requests" in script
        and "generateConnectSid" in script
        and "createConnectSessionPreview" in script
        and "connectErrorFrom returns existing ConnectError" in script
