def check_js_parity_meta_test(errors):
    text = read(JS_PARITY_TEST_PATH)
    require(
        "recursive Kagemusha SDK parity negative controls fail when drift is undetected" in text,
        "JavaScript recursive Kagemusha parity meta-test must pin SDK parity negative controls",
        errors,
    )
    for fragment, label in (
        (
            "Kagemusha SDK parity expectedModes must not contain duplicates",
            "JavaScript recursive Kagemusha parity meta-test must reject duplicate SDK parity modes",
        ),
        (
            'guard.matchAll(/^if mode == "(--negative-control[^"]*)":/gmu)',
            "JavaScript recursive Kagemusha parity meta-test must parse implemented SDK parity modes",
        ),
        (
            "Kagemusha SDK parity expectedModes must equal implemented guard modes",
            "JavaScript recursive Kagemusha parity meta-test must require expected SDK parity modes to equal implemented modes",
        ),
        (
            "Kagemusha production readiness expectedModes must not contain duplicates",
            "JavaScript recursive Kagemusha parity meta-test must reject duplicate production readiness modes",
        ),
        (
            "workflow negative-control helper rejects duplicate expected modes",
            "JavaScript recursive Kagemusha parity meta-test must test workflow negative-control duplicate rejection",
        ),
        (
            "workflow expected negative-control modes must not contain duplicates",
            "JavaScript recursive Kagemusha parity meta-test must reject duplicate workflow negative-control modes",
        ),
    ):
        require(fragment in text, label, errors)
    for _label, command in SDK_PARITY_NEGATIVE_CONTROL_COMMANDS:
        prefix = f"{SDK_PARITY_MAIN_COMMAND} "
        mode = command[len(prefix):] if command.startswith(prefix) else command
        require(
            f'"{mode}"' in text,
            f"JavaScript recursive Kagemusha parity meta-test must pin {mode}",
            errors,
        )


def check_c_bridge(texts, errors):
    rust = texts["crates/connect_norito_bridge/src/lib.rs"]
    header = texts["crates/connect_norito_bridge/include/connect_norito_bridge.h"]
    umbrella = texts["crates/connect_norito_bridge/include/NoritoBridge.h"]

    rust_exports = names_from_matches(
        rust,
        r'pub\s+unsafe\s+extern\s+"C"\s+fn\s+'
        r"(connect_norito_kagemusha_recursive_spend_[a-z0-9_]+)\s*\(",
    )
    header_exports = names_from_matches(
        header,
        r"int32_t\s+(connect_norito_kagemusha_recursive_spend_[a-z0-9_]+)\s*\(",
    )
    require_same_set(rust_exports, REQUIRED_C_SYMBOLS, "Rust C recursive Kagemusha exports", errors)
    require_same_set(header_exports, REQUIRED_C_SYMBOLS, "C header recursive Kagemusha declarations", errors)
    rust_record_exports = names_from_matches(
        rust,
        r'pub\s+unsafe\s+extern\s+"C"\s+fn\s+'
        r"(connect_norito_kagemusha_(?:prove_verified_compact_payment_token_with_records|prove_verified_recursive_aggregation_proof_bundle_with_records_and_pallas_open_envelopes))\s*\(",
    )
    header_record_exports = names_from_matches(
        header,
        r"int32_t\s+(connect_norito_kagemusha_(?:prove_verified_compact_payment_token_with_records|prove_verified_recursive_aggregation_proof_bundle_with_records_and_pallas_open_envelopes))\s*\(",
    )
    require_same_set(
        rust_record_exports,
        REQUIRED_RECORD_BACKED_KAGEMUSHA_C_SYMBOLS,
        "Rust C record-backed Kagemusha prover exports",
        errors,
    )
    require_same_set(
        header_record_exports,
        REQUIRED_RECORD_BACKED_KAGEMUSHA_C_SYMBOLS,
        "C header record-backed Kagemusha prover declarations",
        errors,
    )
    rust_pallas_builder_exports = names_from_matches(
        rust,
        r'pub\s+unsafe\s+extern\s+"C"\s+fn\s+'
        r"(connect_norito_kagemusha_build_(?:pallas_open_envelopes|previous_proof_open_envelopes)_archive)\s*\(",
    )
    header_pallas_builder_exports = names_from_matches(
        header,
        r"int32_t\s+"
        r"(connect_norito_kagemusha_build_(?:pallas_open_envelopes|previous_proof_open_envelopes)_archive)\s*\(",
    )
    require_same_set(
        rust_pallas_builder_exports,
        REQUIRED_KAGEMUSHA_PALLAS_OPEN_ENVELOPE_BUILDER_C_SYMBOLS,
        "Rust C Kagemusha Pallas open-envelope builder exports",
        errors,
    )
    require_same_set(
        header_pallas_builder_exports,
        REQUIRED_KAGEMUSHA_PALLAS_OPEN_ENVELOPE_BUILDER_C_SYMBOLS,
        "C header Kagemusha Pallas open-envelope builder declarations",
        errors,
    )
    require_contains(
        texts,
        "crates/connect_norito_bridge/include/connect_norito_bridge.h",
        (
            "Build metadata-bound Pallas open envelopes",
            "one envelope per hop",
            "Build the one-envelope Pallas opening archive required for reserved-lineage append",
            "KagemushaRecursiveSpendBundleV1",
        ),
        "C header Kagemusha Pallas open-envelope builder contract",
        errors,
    )
    require(
        re.search(
            r'pub\s+unsafe\s+extern\s+"C"\s+fn\s+connect_norito_bridge_abi_version\s*\(',
            rust,
        )
        is not None,
        "Rust C bridge missing connect_norito_bridge_abi_version export",
        errors,
    )
    require(
        re.search(
            r"uint32_t\s+connect_norito_bridge_abi_version\s*\(\s*void\s*\)\s*;",
            header,
        )
        is not None,
        "C header missing connect_norito_bridge_abi_version declaration",
        errors,
    )
    require('#include "connect_norito_bridge.h"' in umbrella, "NoritoBridge.h must include connect_norito_bridge.h", errors)
    require_regex(
        texts,
        "crates/connect_norito_bridge/src/lib.rs",
        r"CONNECT_NORITO_BRIDGE_ABI_VERSION\s*:\s*u32\s*=\s*10\s*;",
        "C native bridge ABI version",
        errors,
    )
    require_contains(
        texts,
        "crates/connect_norito_bridge/src/lib.rs",
        (
            "zero-envelope Pallas archive",
            "zero-envelope nested Pallas archives",
        ),
        "Rust C recursive spend nested Pallas guard",
        errors,
    )
    require_contains(
        texts,
        "crates/connect_norito_bridge/src/lib.rs",
        (
            "zk1_i10p_parser_rejects_empty_truncated_and_trailing_payloads",
            "I10P payloads with trailing bytes must not be partially decoded",
            "I10P payloads with missing scalar bytes must reject",
            '"zero columns"',
            '"zero rows"',
            '"too many columns"',
            '"too many rows"',
            "zk1_read_instance_columns(&payload).is_none()",
        ),
        "Rust native bridge ZK1 I10P parser exactness tests",
        errors,
    )
    recursive_compact_default_start = rust.find(
        "fn kagemusha_recursive_compact_ffi_fails_closed_and_rejects_adversarial_inputs_impl()"
    )
    recursive_compact_ignored_start = rust.find(
        "fn kagemusha_recursive_compact_ffi_shape_valid_invalid_proof_returns_soft_invalid()"
    )
    require(
        recursive_compact_default_start != -1,
        "Rust native recursive compact default adversarial test missing",
        errors,
    )
    require(
        recursive_compact_ignored_start != -1,
        "Rust native recursive compact invalid-proof soft-invalid backend test missing",
        errors,
    )
    if recursive_compact_default_start != -1 and recursive_compact_ignored_start != -1:
        require(
            "sample_recursive_compact_shape_valid_invalid_proof_token"
            not in rust[recursive_compact_default_start:recursive_compact_ignored_start],
            "Rust native recursive compact default adversarial test must not enter minimum-sized invalid-proof backend verification",
            errors,
        )
    require(
        re.search(
            r'#\[test\]\s*#\[ignore = "heavy Kagemusha Halo2 IPA invalid-proof verification; run explicitly with --ignored --test-threads=1"\]\s*fn kagemusha_recursive_compact_ffi_shape_valid_invalid_proof_returns_soft_invalid',
            rust,
        )
        is not None,
        "Rust native recursive compact invalid-proof soft-invalid backend test must be ignored",
        errors,
    )
    require_contains(
        texts,
        "crates/connect_norito_bridge/src/lib.rs",
        (
            "fn parse_identifier_exact_str(value: &JsonValue) -> BridgeResult<String>",
            "raw.is_empty() || raw.trim() != raw",
            ".decode(proof_b64)",
            "let kind =\n        parse_identifier_exact_str",
            "parse_identifier_receipt_rejects_padded_payload_fields",
            "parse_identifier_receipt_rejects_padded_proof_attestation_fields",
            'vec!["payload", "opaque_id"]',
            'vec!["payload", "uaid"]',
            'vec!["payload", "account_id"]',
            'vec!["attestation", "kind"]',
            "padded policy-id object fields must fail",
        ),
        "Rust native identifier receipt exactness",
        errors,
    )
    require_regex(
        texts,
        "crates/connect_norito_bridge/src/lib.rs",
        r"let\s+account_id\s*=\s*parse_identifier_exact_str\([\s\S]*?"
        r"\.and_then\(\|value\|\s*parse_account_id\(value\)"
        r"\.map_err\(\|_\|\s*BridgeError::IdentifierReceipt\)\)\?;",
        "Rust native identifier receipt account-id exactness",
        errors,
    )
    require_contains(
        texts,
        "crates/connect_norito_bridge/src/lib.rs",
        (
            "fn validate_identifier_claim_account(",
            "if &receipt.payload.account_id != account",
            "validate_identifier_claim_account(&account, &receipt)?;",
            "validate_identifier_claim_account_rejects_mismatched_receipt_account",
            "mismatched claim account must fail before transaction encoding",
        ),
        "Rust native claim identifier account binding",
        errors,
    )
    require_regex(
        texts,
        "crates/connect_norito_bridge/src/lib.rs",
        r"let private_key = parse_private_key\(key_slice\)\?;\s*"
        r"let receipt = parse_identifier_receipt_bytes\(receipt_ptr, receipt_len\)\?;\s*"
        r"validate_identifier_claim_account\(&account, &receipt\)\?;\s*"
        r"let \(signed_bytes, hash_bytes\) = encode_instruction_transaction\(",
        "Rust native claim identifier transaction account binding",
        errors,
    )
    require_regex(
        texts,
        "crates/connect_norito_bridge/src/lib.rs",
        r"let private_key = parse_private_key_with_algorithm\(key_slice, algorithm\)\?;\s*"
        r"let receipt = parse_identifier_receipt_bytes\(receipt_ptr, receipt_len\)\?;\s*"
        r"validate_identifier_claim_account\(&account, &receipt\)\?;\s*"
        r"let \(signed_bytes, hash_bytes\) = encode_instruction_transaction\(",
        "Rust native claim identifier algorithm transaction account binding",
        errors,
    )

    for package in ("android", "sdk"):
        for method in JNI_METHODS:
            symbol = f"Java_org_hyperledger_iroha_{package}_offline_KagemushaRecursiveSpendProver_{method}"
            require(symbol in rust, f"JNI export missing {symbol}", errors)


