    require_regex(
        texts,
        dts,
        r"export\s+function\s+kagemushaVerifyRecursiveCompactPaymentToken\s*"
        r"\(\s*compactTokenArchive:\s*BinaryLike\s*,\s*recursiveCompactVerifierKeysArchive:\s*BinaryLike\s*,\s*\)"
