def check_record_backed_javascript_surface(texts, errors):
    require_contains(
        texts,
        "crates/iroha_js_host/src/lib.rs",
        [f'js_name = "{name}"' for name in REQUIRED_RECORD_BACKED_KAGEMUSHA_JS_METHODS]
        + [f'js_name = "{name}"' for name in REQUIRED_KAGEMUSHA_PALLAS_OPEN_ENVELOPE_BUILDER_JS_METHODS]
        + [
            "prove_verified_kagemusha_compact_payment_token_from_record_bundle",
            "prove_verified_kagemusha_recursive_aggregation_proof_bundle_from_record_bundle_and_pallas_open_envelope_archive",
            "kagemusha_pallas_open_envelopes_from_record_bundle",
            "kagemusha_recursive_previous_proof_open_envelope_metadata",
            "kagemusha-recursive-spend-hop-open-v1-{hop_index}",
            "kagemusha-recursive-spend-previous-open-v1",
            "KAGEMUSHA_FOLDED_CIRCUIT_ID",
            "KAGEMUSHA_RECURSIVE_AGGREGATION_CIRCUIT_ID",
            "serialize Kagemusha compact payment-token archive",
            "serialize Kagemusha recursive aggregation proof-bundle archive",
            "serialize Kagemusha Pallas open-envelope archive",
            "serialize Kagemusha previous proof open-envelope archive",
        ],
        "Node record-backed Kagemusha prover and Pallas builder exports",
        errors,
    )

    for relative in (
        "javascript/iroha_js/src/crypto.js",
        "javascript/iroha_js/dist/crypto.js",
    ):
        require_contains(
            texts,
            relative,
            REQUIRED_RECORD_BACKED_KAGEMUSHA_JS_PUBLIC_EXPORTS
            + REQUIRED_KAGEMUSHA_PALLAS_OPEN_ENVELOPE_BUILDER_JS_PUBLIC_EXPORTS
            + (
                'typeof native.kagemushaProveVerifiedCompactPaymentTokenWithRecords !== "function"',
                'typeof native.kagemushaBuildPallasOpenEnvelopesArchive !== "function"',
                'typeof native.kagemushaBuildPreviousProofOpenEnvelopesArchive !== "function"',
                "native.kagemushaProveVerifiedCompactPaymentTokenWithRecords(",
                "native.kagemushaProveVerifiedRecursiveAggregationProofBundleWithRecordsAndPallasOpenEnvelopes(",
                "native.kagemushaBuildPallasOpenEnvelopesArchive(",
                "native.kagemushaBuildPreviousProofOpenEnvelopesArchive(",
                "toOwnedKagemushaArchiveBuffer",
                'const recordBundle = toOwnedKagemushaArchiveBuffer(',
                'const pallasOpenEnvelopes = toOwnedKagemushaArchiveBuffer(',
                'const previousBundle = toOwnedKagemushaArchiveBuffer(',
                '"recordBundleArchive"',
                '"pallasOpenEnvelopesArchive"',
                '"previousBundleArchive"',
                "Kagemusha compact payment-token prover requires native bridge ABI 6 with compact-token prover symbol",
                "Kagemusha recursive aggregation proof-bundle prover requires native bridge ABI 6 with recursive aggregation prover symbol",
                "Kagemusha Pallas open-envelope builders require native bridge ABI 7 with Pallas builder symbols",
                "kagemushaProveVerifiedCompactPaymentTokenWithRecords",
                "kagemushaProveVerifiedRecursiveAggregationProofBundleWithRecordsAndPallasOpenEnvelopes",
                "kagemushaBuildPallasOpenEnvelopesArchive",
                "kagemushaBuildPreviousProofOpenEnvelopesArchive",
            ),
            "JavaScript record-backed Kagemusha prover and Pallas builder wrappers",
            errors,
        )
    for relative in (
        "javascript/iroha_js/src/crypto.browser.js",
        "javascript/iroha_js/dist/crypto.browser.js",
    ):
        require_contains(
            texts,
            relative,
            REQUIRED_RECORD_BACKED_KAGEMUSHA_JS_PUBLIC_EXPORTS
            + REQUIRED_KAGEMUSHA_PALLAS_OPEN_ENVELOPE_BUILDER_JS_PUBLIC_EXPORTS
            + (
                "return false;",
                'unsupported("kagemushaProveVerifiedCompactPaymentTokenWithRecords")',
                'unsupported(\n    "kagemushaProveVerifiedRecursiveAggregationProofBundleWithRecordsAndPallasOpenEnvelopes"',
                'unsupported("kagemushaBuildPallasOpenEnvelopesArchive")',
                'unsupported("kagemushaBuildPreviousProofOpenEnvelopesArchive")',
            ),
            "JavaScript browser record-backed Kagemusha and Pallas builder stubs",
            errors,
        )
    for relative in ("javascript/iroha_js/src/index.js", "javascript/iroha_js/dist/index.js"):
        require_contains(
            texts,
            relative,
            REQUIRED_RECORD_BACKED_KAGEMUSHA_JS_PUBLIC_EXPORTS
            + REQUIRED_KAGEMUSHA_PALLAS_OPEN_ENVELOPE_BUILDER_JS_PUBLIC_EXPORTS,
            f"{relative} record-backed Kagemusha and Pallas builder re-exports",
            errors,
        )
    require_contains(
        texts,
        "javascript/iroha_js/index.d.ts",
        (
            "isKagemushaCompactPaymentTokenNativeAvailable(): boolean",
            "isKagemushaRecursiveAggregationProofBundleNativeAvailable(): boolean",
            "isKagemushaPallasOpenEnvelopeBuilderNativeAvailable(): boolean",
            "kagemushaProveVerifiedCompactPaymentTokenWithRecords(",
            "kagemushaProveVerifiedRecursiveAggregationProofBundleWithRecordsAndPallasOpenEnvelopes(",
            "kagemushaBuildPallasOpenEnvelopesArchive(",
            "kagemushaBuildPreviousProofOpenEnvelopesArchive(",
        ),
        "JavaScript record-backed Kagemusha and Pallas builder TypeScript declarations",
        errors,
    )
    require_contains(
        texts,
        "javascript/iroha_js/test/kagemushaRecursiveSpend.test.js",
        (
            "Kagemusha record-backed JS builders probe availability and validate native output",
            "Kagemusha Pallas open-envelope JS builders probe availability and validate native output",
            "isKagemushaCompactPaymentTokenNativeAvailable",
            "isKagemushaRecursiveAggregationProofBundleNativeAvailable",
            "isKagemushaPallasOpenEnvelopeBuilderNativeAvailable",
            "recordBundleArchive must be a valid Norito archive",
            "previousBundleArchive must be a valid Norito archive",
            "pallasOpenEnvelopesArchive must contain a non-empty Norito payload",
            "returned invalid Norito archive",
            "returned empty Norito payload",
            "native kagemushaBuildPallasOpenEnvelopesArchive returned invalid Norito archive",
            "native kagemushaBuildPreviousProofOpenEnvelopesArchive returned invalid Norito archive",
            "native kagemushaBuildPallasOpenEnvelopesArchive returned empty Norito payload",
            "native kagemushaBuildPreviousProofOpenEnvelopesArchive returned empty Norito payload",
            "Kagemusha Pallas open-envelope builders require native bridge ABI 7",
        ),
        "JavaScript record-backed Kagemusha and Pallas builder runtime tests",
        errors,
    )
    require_contains(
        texts,
        "javascript/iroha_js/test/package_dist.test.js",
        (
            "package dist Kagemusha record-backed and Pallas builders dispatch owned archives",
            "isKagemushaCompactPaymentTokenNativeAvailable()",
            "isKagemushaRecursiveAggregationProofBundleNativeAvailable()",
            "isKagemushaPallasOpenEnvelopeBuilderNativeAvailable()",
            "kagemushaProveVerifiedCompactPaymentTokenWithRecords(",
            "kagemushaProveVerifiedRecursiveAggregationProofBundleWithRecordsAndPallasOpenEnvelopes(",
            "kagemushaBuildPallasOpenEnvelopesArchive(",
            "kagemushaBuildPreviousProofOpenEnvelopesArchive(",
            "assert.notStrictEqual(calls[0][1], recordBundle)",
            "assert.notStrictEqual(calls[1][2], pallasOpenEnvelopes)",
            "assert.notStrictEqual(calls[3][1], previousBundle)",
            "assert.deepEqual(result, expectedOutputs.get(methodName), methodName)",
        ),
        "JavaScript package record-backed Kagemusha and Pallas builder dispatch coverage",
        errors,
    )
    require_contains(
        texts,
        "javascript/iroha_js/test/package_dist.test.js",
        (
            "package dist Kagemusha record-backed and Pallas builders fail closed on invalid archives",
            "const invalidArchives = [",
            "[Buffer.alloc(0), \"must not be empty\"]",
            "[Buffer.from([0x01]), \"must be a valid Norito archive\"]",
            "[privacyNoritoFrame(0x98), \"must contain a non-empty Norito payload\"]",
            "[Buffer.alloc(KAGEMUSHA_NATIVE_ARCHIVE_MAX_BYTES + 1, 0x7f), \"must not exceed\"]",
            "[undefined, \"must be a Buffer, string, or ArrayBuffer view\"]",
            "recordBundleArchive ${expectedMessage}",
            "pallasOpenEnvelopesArchive ${expectedMessage}",
            "previousBundleArchive ${expectedMessage}",
            "assert.equal(nativeDispatches, 0)",
            "native kagemushaProveVerifiedCompactPaymentTokenWithRecords returned invalid Norito archive",
            "native kagemushaProveVerifiedRecursiveAggregationProofBundleWithRecordsAndPallasOpenEnvelopes returned empty Norito payload",
            "native kagemushaBuildPallasOpenEnvelopesArchive returned invalid Norito archive",
            "native kagemushaBuildPreviousProofOpenEnvelopesArchive returned empty Norito payload",
        ),
        "JavaScript package record-backed Kagemusha and Pallas builder fail-closed coverage",
        errors,
    )
    require_contains(
        texts,
        "javascript/iroha_js/test/package_dist.test.js",
        (
            "const invalidArchives = [\n"
            "    [Buffer.alloc(0), \"must not be empty\"],\n"
            "    [Buffer.from([0x01]), \"must be a valid Norito archive\"],\n"
            "    [privacyNoritoFrame(0x98), \"must contain a non-empty Norito payload\"],\n"
            "    [Buffer.alloc(KAGEMUSHA_NATIVE_ARCHIVE_MAX_BYTES + 1, 0x7f), \"must not exceed\"],\n"
            "    [undefined, \"must be a Buffer, string, or ArrayBuffer view\"],\n"
            "  ];",
        ),
        "JavaScript package record-backed Kagemusha and Pallas builder oversized fail-closed coverage",
        errors,
    )
    require_contains(
        texts,
        "javascript/iroha_js/test/package_dist.test.js",
        (
            "[Buffer.alloc(KAGEMUSHA_NATIVE_ARCHIVE_MAX_BYTES + 1, 0x7f), \"must not exceed\"],\n"
            "    [undefined, \"must be a Buffer, string, or ArrayBuffer view\"],",
        ),
        "JavaScript package record-backed Kagemusha and Pallas builder missing-archive fail-closed coverage",
        errors,
    )
    require_contains(
        texts,
        "javascript/iroha_js/test/crypto.browser.test.js",
        REQUIRED_RECORD_BACKED_KAGEMUSHA_JS_PUBLIC_EXPORTS
        + REQUIRED_KAGEMUSHA_PALLAS_OPEN_ENVELOPE_BUILDER_JS_PUBLIC_EXPORTS
        + (
            "browser build must not expose native compact-token prover",
            "browser build must not expose native recursive aggregation prover",
            "browser build must not expose native Pallas open-envelope builders",
        ),
        "JavaScript browser record-backed Kagemusha and Pallas builder tests",
        errors,
    )
    require_contains(
        texts,
        "javascript/iroha_js/test/package_dist.test.js",
        REQUIRED_RECORD_BACKED_KAGEMUSHA_JS_PUBLIC_EXPORTS
        + REQUIRED_KAGEMUSHA_PALLAS_OPEN_ENVELOPE_BUILDER_JS_PUBLIC_EXPORTS,
        "JavaScript package record-backed Kagemusha and Pallas builder exports",
        errors,
    )


def check_rust_policy_constants(texts, errors):
    relative = "crates/iroha_data_model/src/offline/mod.rs"
    core = "crates/iroha_core/src/zk.rs"
    require_regex(
        texts,
        relative,
        r'KAGEMUSHA_RECURSIVE_AGGREGATION_PROOF_CIRCUIT_ID_V1:\s*&str\s*=\s*"kagemusha-recursive-aggregation-v1"',
        "Rust aggregation circuit id",
        errors,
    )
    require_regex(
        texts,
        relative,
        r'KAGEMUSHA_RECURSIVE_SPEND_LINEAGE_PROOF_CIRCUIT_ID_V1:\s*&str\s*=\s*"kagemusha-recursive-spend-lineage-v1"',
        "Rust Reserved-lineage circuit id",
        errors,
    )
    require_regex(
        texts,
        relative,
        r"KAGEMUSHA_RECURSIVE_SPEND_LINEAGE_WITNESSLESS_MAX_HOPS_V1\s*:\s*u32\s*=\s*64\s*;",
        "Rust witnessless max hops",
        errors,
    )
    require_regex(
        texts,
        relative,
        r"KAGEMUSHA_RECURSIVE_SPEND_LINEAGE_TRANSITION_CIRCUIT_WIRED_V1\s*:\s*bool\s*=\s*true\s*;",
        "Rust transition-circuit wired flag",
        errors,
    )
    require_contains(
        texts,
        relative,
        (
            "proof_circuit_id == KAGEMUSHA_RECURSIVE_SPEND_LINEAGE_PROOF_CIRCUIT_ID_V1",
            "hop_count >= 1",
            "hop_count <= KAGEMUSHA_RECURSIVE_SPEND_LINEAGE_WITNESSLESS_MAX_HOPS_V1",
            "previous_hop_count >= 1",
            "previous_hop_count < KAGEMUSHA_RECURSIVE_SPEND_LINEAGE_WITNESSLESS_MAX_HOPS_V1",
        ),
        "Rust witnessless Reserved-lineage helper bounds",
        errors,
    )
    require_regex(
        texts,
        relative,
        r"KAGEMUSHA_RECURSIVE_PREVIOUS_PROOF_OPEN_ENVELOPES_REQUIRED_COUNT_V1\s*:\s*usize\s*=\s*1\s*;",
        "Rust previous-proof open envelope count",
        errors,
    )
    require_regex(
        texts,
        relative,
        r"KAGEMUSHA_RECURSIVE_PREVIOUS_PROOF_OPEN_ENVELOPES_MAX_BYTES\s*:\s*usize\s*=\s*8\s*\*\s*1024\s*\*\s*1024\s*;",
        "Rust previous-proof open envelope max bytes",
        errors,
    )
    require_regex(
        texts,
        relative,
        r"KAGEMUSHA_RECURSIVE_PALLAS_OPEN_ENVELOPE_MAX_TRANSCRIPT_LABEL_BYTES\s*:\s*usize\s*=\s*128\s*;",
        "Rust Pallas open-envelope transcript label max bytes",
        errors,
    )
    require_contains(
        texts,
        core,
        (
            "KAGEMUSHA_CONFIDENTIAL_TRANSFER_V2_PUBLIC_INSTANCE_COLUMNS: usize = 9",
            "ensure_kagemusha_confidential_v2_public_instance_shape(&instance_columns)?;",
            "Kagemusha fold Halo2/IPA confidential-transfer-v2 proof must expose exactly",
            "single-row public instance columns",
            "found {} columns",
            "column {column_index} has {} rows",
            "kagemusha_proof_statement_digest_rejects_noncanonical_halo2_public_instance_shape",
            "extra public instance column must reject before proof verification",
            "multi-row public instance column must reject before proof verification",
        ),
        "Rust Kagemusha hop public-instance shape",
        errors,
    )
    require_contains(
        texts,
        "docs/source/offline_kagemusha.md",
        (
            "exactly nine single-row public instance columns",
            "extra",
            "public columns or rectangular multi-row ZK1 instance payloads reject",
            "folded transcript or Pallas opening metadata",
        ),
        "offline Kagemusha hop public-instance shape docs",
        errors,
    )
    require_contains(
        texts,
        core,
        (
            "if step.root_before == step.root_after",
            "Kagemusha fold hop {hop_index} must change the Merkle root",
            "kagemusha_verified_folded_public_inputs_rejects_unchanged_root_before_proof_decode",
            "unchanged root transition must reject before proof decode",
            "record-backed unchanged root transition must reject before proof decode",
            "kagemusha_verified_folded_public_inputs_rejects_root_discontinuity_before_proof_decode",
            "does not continue from the previous root",
        ),
        "Rust Kagemusha fold root-transition preflight",
        errors,
    )

def check_node_host(texts, errors):
    relative = "crates/iroha_js_host/src/lib.rs"
    require_contains(
        texts,
        relative,
        [f'js_name = "{name}"' for name in REQUIRED_JS_NATIVE_METHODS],
        "Node NAPI host",
        errors,
    )
    require_regex(
        texts,
        relative,
        r"pub\s+fn\s+connect_norito_bridge_abi_version\s*\(\)\s*->\s*u32\s*\{\s*8\s*\}",
        "Node NAPI native bridge ABI version",
        errors,
    )


