        errors,
    )
    require_contains(
        texts,
        "python/iroha_python/src/iroha_python/kagemusha.py",
        (
            "def _kagemusha_read_topup_anchor_nullifiers(",
            "_kagemusha_read_topup_anchor_nullifiers(",
            "count > KAGEMUSHA_FOLD_STEP_MAX_INPUTS",
